import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/TDLearning.html","title":"TDLearning","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":0.41,"words":122},"filePathRelative":"TDLearning.md"}`),a={name:`TDLearning.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="tdlearning" tabindex="-1"><a class="header-anchor" href="#tdlearning"><span>TDLearning</span></a></h1><p>Temporal Difference Learningとも言う。<a href="./ModelFreePolicyEvaluation.html">ModelFreePolicyEvaluation</a>の一種。</p><h2 id="td-learningとは" tabindex="-1"><a class="header-anchor" href="#td-learningとは"><span>TD Learningとは</span></a></h2><p><img src="/RandomThoughts/assets/0008-BnnDf_X7.png" alt="imgs/CS234Lec3/0008.png"></p><p>つまりGの見積もりとしてエピソード全体を使うのでは無く、そこまでの推計のVと今回のrewardsを組み合わせたものを使う。 １期のrewardsしか使っていない事に注目。（<a href="./モンテカルロPolicyEvaluation.html">モンテカルロPolicyEvaluation</a>のインクリメンタルとの違い）</p><h2 id="mars-roverでの例" tabindex="-1"><a class="header-anchor" href="#mars-roverでの例"><span>Mars Roverでの例</span></a></h2><p><img src="/RandomThoughts/assets/0009-C0fUZLMa.png" alt="imgs/CS234Lec3/0009.png"></p><h2 id="特徴など" tabindex="-1"><a class="header-anchor" href="#特徴など"><span>特徴など</span></a></h2><ul><li>モンテカルロとdynamic programmingのハイブリッド的なもの</li><li>ブートストラップとサンプリング <ul><li>ブートストラッピングは自分自身を足場に自分自身を引き上げる、というようなニュアンスで、Vの更新の時にその時点のV自身の予測値を使っている、というような意味らしい（V(A)を更新する時にその時点のV(B)を使ったりしている）</li></ul></li><li>有限地平で無くても使える（エピソード的なセッティングじゃなくてもOK）</li><li>(s, a, r, s&#39;)のタプルが来るごとにその場で更新</li><li>最初の頃は初期化によるのでbiasedなestimator</li><li>インクリメンタルな<a href="./モンテカルロPolicyEvaluation.html">モンテカルロPolicyEvaluation</a>と同じ条件で<a href="./ConsistentEstimator.html">ConsistentEstimator</a>になる</li><li><a href="./モンテカルロPolicyEvaluation.html">モンテカルロPolicyEvaluation</a>よりvarianceが低い</li></ul><h2 id="policy-improvementでの使用。" tabindex="-1"><a class="header-anchor" href="#policy-improvementでの使用。"><span>Policy Improvementでの使用。</span></a></h2><p><a href="./ModelFreePolicyImprovement.html">ModelFreePolicyImprovement</a>へ。<a href="./SARSA.html">SARSA</a>と<a href="./QLearning.html">QLearning</a>がある。</p>`,11)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};